CREATE TEMP TABLE new_stub (seat_id uuid, name text, party_name text, photo_url text, stub_id uuid) ON COMMIT DROP;
INSERT INTO new_stub (seat_id, name, party_name, photo_url, stub_id) VALUES ('f66d0c6e-a32d-4100-8ae5-65345b9ec102','Tina Fiorda','Restore Burnaby','https://www.burnaby.ca/sites/default/files/styles/portrait_148w_/public/acquiadam/2026-09/COU_FIORDA%20Tina_Photo-Resized.JPG?h=f6ba2071&itok=kqOBMtGS',gen_random_uuid()),
('f66d0c6e-a32d-4100-8ae5-65345b9ec102','Morgan Nicholsfigueiredo','NEW Burnaby','https://www.burnaby.ca/sites/default/files/styles/portrait_148w_/public/acquiadam/2026-09/COU_NICHOLSFIGUEIREDO%20Morgan_Photo-Resized.jpg?h=9705ee69&itok=SVSVAzA0',gen_random_uuid()),
('f66d0c6e-a32d-4100-8ae5-65345b9ec102','Vincent Tong',NULL,NULL,gen_random_uuid()),
('f66d0c6e-a32d-4100-8ae5-65345b9ec102','Sabrina Yang','NEW Burnaby',NULL,gen_random_uuid());
INSERT INTO public.profiles (id, role, full_name, onboarding_completed, country, current_ghost_id) SELECT stub_id, 'politician', name, true, 'Canada', gen_random_uuid() FROM new_stub;
INSERT INTO public.politician_profiles (id, political_party_id, avatar_url, photo_url) SELECT ns.stub_id, pp.id, ns.photo_url, ns.photo_url FROM new_stub ns LEFT JOIN public.political_parties pp ON pp.country='Canada' AND pp.name = ns.party_name;
INSERT INTO public.election_candidates (seat_id, politician_id, status, submitted_at, added_by_election_admin_id) SELECT seat_id, stub_id, 'approved', now(), '5b66563e-2674-4fed-b733-3e19955a166a' FROM new_stub;
COMMIT;
